options.getOption:
// The fire calendar: one row per year, one column per month, each cell the
// share of that year's detections that fell in that month. Shares rather than
// counts, because the counts grow with every satellite NASA adds (VIIRS joined
// in 2012, 2018 and 2024); a share compares seasons across the whole record.
// It follows the country pick and the drawn area, not the time window, whose
// months are outlined.
//
// Click a cell: the time brush moves to that month, on the daily archive for
// the current year and the monthly one before it.
// @constants begin
const T0 = 't0';
const T1 = 't1';
const ARCHIVE = 'archive';
const COLORS = ['#1F1F24', '#5C0A0A', '#9B1C1C', '#D9480F', '#F08C00', '#FCC419', '#FFF3BF'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
// @constants end

const chart = context.panel.chart;
const theme = context.grafana.theme;
const location = context.grafana.locationService;
const muted = theme.colors.text.secondary;

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const years = col('year').map(Number);
const months = col('month').map(Number);
const counts = col('detections').map(Number);
const shares = col('share').map(Number);

const first = years.length ? Math.min(...years) : 2000;
const last = years.length ? Math.max(...years) : 2000;
const rows = [];
for (let y = last; y >= first; y--) { // newest first, drawn at the top by inverse
  rows.push(String(y));
}
const data = years.map((y, i) => [months[i] - 1, String(y), shares[i], counts[i]]);
// The scale tops out at the largest share of a whole year: 2000 has only two
// months, so its shares would flatten every other row. Larger ones clamp.
const monthsIn = {};
years.forEach((y) => (monthsIn[y] = (monthsIn[y] || 0) + 1));
const top = Math.max(0.0001, ...shares.filter((s, i) => monthsIn[years[i]] === 12));

// ${t0} ${t1}: named literally so the outline follows the brush.
const t0 = Date.parse(context.grafana.replaceVariables('${' + T0 + '}'));
const t1 = Date.parse(context.grafana.replaceVariables('${' + T1 + '}'));
const inWindow = (y, m) => {
  if (!Number.isFinite(t0) || !Number.isFinite(t1)) {
    return false;
  }
  const start = Date.UTC(y, m, 1);
  const end = Date.UTC(y, m + 1, 1);
  return start < t1 && end > t0;
};
const cells = data.map((v) =>
  inWindow(Number(v[1]), v[0]) ? { value: v, itemStyle: { borderColor: theme.colors.text.primary, borderWidth: 2 } } : v
);

const thisYear = new Date().getUTCFullYear();
chart.off('click');
chart.on('click', (event) => {
  const [m, y] = event.value;
  const year = Number(y);
  location.partial(
    {
      ['var-' + T0]: new Date(Date.UTC(year, m, 1)).toISOString(),
      ['var-' + T1]: new Date(Date.UTC(year, m + 1, 1)).toISOString(),
      ['var-' + ARCHIVE]: year === thisYear ? 'day' : 'month',
    },
    true
  );
});

const big = (v) => (v >= 1e6 ? `${(v / 1e6).toFixed(1)} M` : v >= 1e3 ? `${Math.round(v / 1e3)} k` : String(v));

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 16, top: 8, bottom: 48, containLabel: true },
  tooltip: {
    formatter: (p) =>
      `<b>${MONTHS[p.value[0]]} ${p.value[1]}</b><br/>${(p.value[2] * 100).toFixed(1)} % of the year<br/>${big(p.value[3])} detections`,
  },
  xAxis: { type: 'category', data: MONTHS, axisLabel: { color: muted }, axisTick: { show: false }, splitArea: { show: false } },
  yAxis: { type: 'category', data: rows, inverse: true, axisLabel: { color: muted, fontSize: 10 }, axisTick: { show: false } },
  visualMap: {
    min: 0,
    max: top,
    calculable: false,
    orient: 'horizontal',
    left: 'center',
    bottom: 0,
    itemHeight: 160,
    itemWidth: 10,
    text: [`${(top * 100).toFixed(0)} % of the year`, '0'],
    textStyle: { color: muted },
    inRange: { color: COLORS },
    dimension: 2, // the share; dimension 3 is the count
  },
  series: [
    { type: 'heatmap', data: cells, cursor: 'pointer', itemStyle: { borderColor: 'rgba(0, 0, 0, 0.5)', borderWidth: 1 } },
  ],
};

