options.getOption:
// The countries where most fire burned in the window, the fifteen largest,
// coloured by continent. The query hands one row per country with the measure
// in column VALUE; it follows every other filter but not its own pick, so the
// alternatives stay in sight.
//
// Click a bar: the other panels keep that country only and the map flies to
// the middle of its fire (weighted by the measure). Click it again to clear.
// @constants begin
const VALUE = 'detections';
const SCALE = 1;
const AXIS = 'detections';
const TIP = (v) => `Detections: <b>${v.toLocaleString()}</b>`;
const VAR = 'country';
const LAT = 'clat';
const LNG = 'clng';
const CONTINENTS = {
  Africa: 'orange',
  'South America': 'green',
  'North America': 'blue',
  Asia: 'red',
  Europe: 'purple',
  Oceania: 'yellow',
  Ocean: 'text',
};
// @constants end

// Short numbers: 3786, 12.5, 0.48; thousands and millions as k and M.
const fmt = (v) =>
  v === 0 ? '0' : v >= 1e6 ? `${(v / 1e6).toFixed(1)}M` : v >= 1e4 ? `${Math.round(v / 1e3)}k` : v >= 10 ? v.toFixed(0) : v >= 1 ? v.toFixed(1) : v.toFixed(2);

const chart = context.panel.chart;
const theme = context.grafana.theme;
const location = context.grafana.locationService;
const muted = theme.colors.text.secondary;

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const countries = col('country');
const continents = col('continent');
const values = col(VALUE).map((v) => Number(v) * SCALE);
const detections = col('detections').map(Number);
const lats = col('latitude').map(Number);
const lngs = col('longitude').map(Number);

// ${country}: named literally so the panel redraws when the pick changes.
const picked = context.grafana.replaceVariables('${' + VAR + '}');
const colorOf = (continent) => theme.visualization.getColorByName(CONTINENTS[continent] || 'text');

chart.off('click');
chart.on('click', (event) => {
  const i = event.dataIndex;
  const name = countries[i];
  const same = name === picked;
  location.partial(
    {
      ['var-' + VAR]: same ? '' : name,
      ['var-' + LAT]: same || !Number.isFinite(lats[i]) ? '' : lats[i].toFixed(3),
      ['var-' + LNG]: same || !Number.isFinite(lngs[i]) ? '' : lngs[i].toFixed(3),
    },
    true
  );
});


return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 48, top: 8, bottom: 24, containLabel: true },
  tooltip: {
    trigger: 'item',
    formatter: (p) =>
      `<b>${countries[p.dataIndex]}</b> · ${continents[p.dataIndex]}<br/>` + TIP(values[p.dataIndex], p.dataIndex),
  },
  xAxis: {
    type: 'value',
    name: AXIS,
    nameLocation: 'middle',
    nameGap: 22,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted, formatter: fmt },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  yAxis: {
    type: 'category',
    inverse: true,
    data: countries,
    axisLabel: { color: theme.colors.text.primary, width: 120, overflow: 'truncate' },
    axisTick: { show: false },
  },
  series: [
    {
      type: 'bar',
      barWidth: '70%',
      cursor: 'pointer',
      data: values.map((v, i) => ({
        value: v,
        itemStyle: {
          color: colorOf(continents[i]),
          opacity: picked === '' || countries[i] === picked ? 1 : 0.3,
          borderColor: countries[i] === picked ? theme.colors.text.primary : undefined,
          borderWidth: countries[i] === picked ? 1.5 : 0,
        },
      })),
      label: { show: true, position: 'right', color: muted, formatter: (p) => fmt(p.value) },
    },
  ],
};

